// ─── File: OtpServiceDemo.java ───
// OTP service: Resend re-sends existing OTP + multi-level limits + queue + failover + TOTP.
// Each class below would be its own file in a real project.
package com.bank.otp;

import java.util.logging.*;

public class OtpServiceDemo {

    private static final Logger log = Logger.getLogger("Otp");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OtpStore store = new OtpStore(300_000);         // 5-min TTL
        RateLimiters limits = new RateLimiters();
        ProviderRouter router = new ProviderRouter();

        // Rajesh requests an OTP → generate once, enqueue a send.
        requestOtp(store, limits, router, "RAJESH", "10.1.1.9", false);

        // Rajesh taps Resend 3 times during a spike → re-send EXISTING OTP, no new generation.
        for (int i = 0; i < 3; i++) resendOtp(store, limits, router, "RAJESH");

        // An abusive IP hammers OTPs for many users → per-IP limit → CAPTCHA.
        for (int i = 0; i < 25; i++) requestOtp(store, limits, router, "USER" + i, "66.66.66.66", false);

        // Provider-independent fallback: TOTP needs NO SMS at all.
        TotpVerifier totp = new TotpVerifier();
        boolean ok = totp.verify("RAJESH", totp.currentCodeFor("RAJESH"));
        log.info(() -> "TOTP fallback verify for Rajesh = " + ok + " (zero provider load)");
    }

    static void requestOtp(OtpStore store, RateLimiters limits, ProviderRouter router,
                           String user, String ip, boolean highValue) {
        if (!limits.allowUser(user)) { log.warning(() -> "per-user limit hit for " + user); return; }
        if (!limits.allowIp(ip))     { log.warning(() -> "per-IP limit → CAPTCHA for " + ip); return; }
        String code = store.generate(user);                 // generate + store with TTL
        router.enqueueSend(user, code, highValue);           // queue (TTL + priority), drains at provider rate
    }

    static void resendOtp(OtpStore store, RateLimiters limits, ProviderRouter router, String user) {
        String existing = store.currentValid(user);          // THE KEY FIX
        if (existing == null) { log.info(() -> "no valid OTP, generating new for " + user);
            requestOtp(store, limits, router, user, "resend", false); return; }
        if (!limits.allowResend(user)) { log.warning(() -> "resend cooldown for " + user); return; }
        router.enqueueSend(user, existing, false);            // RE-SEND same code, no new generation
        log.info(() -> "RESEND existing OTP for " + user + " (no amplification)");
    }
}

// ─── store/OtpStore.java ───  Redis-like store with TTL
class OtpStore {
    private static final Logger log = Logger.getLogger("Otp");
    private final long ttlMs;
    private final java.util.Map<String, long[]> meta = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<String, String> codes = new java.util.concurrent.ConcurrentHashMap<>();

    OtpStore(long ttlMs) { this.ttlMs = ttlMs; }

    String generate(String user) {
        String code = String.format("%06d", new java.util.Random().nextInt(1_000_000));
        codes.put(user, code);
        meta.put(user, new long[]{ System.currentTimeMillis() + ttlMs });
        log.info(() -> "generated OTP for " + user + " (valid " + (ttlMs/1000) + "s)");
        return code;
    }
    // returns the existing code ONLY if still valid → enables Resend-without-new-generation
    String currentValid(String user) {
        long[] m = meta.get(user);
        if (m == null || System.currentTimeMillis() > m[0]) return null;  // expired
        return codes.get(user);
    }
}

// ─── limit/RateLimiters.java ───  multi-level limits
class RateLimiters {
    private final java.util.Map<String, Integer> userCount = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<String, Integer> ipCount = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<String, Long> lastResend = new java.util.concurrent.ConcurrentHashMap<>();

    boolean allowUser(String user) { return userCount.merge(user, 1, Integer::sum) <= 3; }      // 3/window
    boolean allowIp(String ip)     { return ipCount.merge(ip, 1, Integer::sum) <= 20; }         // then CAPTCHA
    boolean allowResend(String user) {                                                           // cooldown
        long now = System.currentTimeMillis();
        Long last = lastResend.get(user);
        if (last != null && now - last < 20_000) return false;
        lastResend.put(user, now); return true;
    }
}

// ─── send/ProviderRouter.java ───  TTL+priority queue, per-provider token bucket, failover
class ProviderRouter {
    private static final Logger log = Logger.getLogger("Otp");
    private int primaryTokens = 10000, secondaryTokens = 5000;   // buckets per provider

    void enqueueSend(String user, String code, boolean highValue) {
        // real impl: push to a priority queue with TTL; workers drain at provider rate.
        if (primaryTokens-- > 0) {
            log.fine(() -> "SMS-PRIMARY → " + user + " code " + code + (highValue ? " [HIGH]" : ""));
        } else if (secondaryTokens-- > 0) {
            log.warning(() -> "SMS-PRIMARY empty → FAILOVER SMS-SECONDARY → " + user);  // clean failover
        } else {
            log.severe(() -> "all providers exhausted → queue/TTL-shed or email fallback for " + user);
        }
    }
}

// ─── fallback/TotpVerifier.java ───  provider-independent (no SMS)
class TotpVerifier {
    String currentCodeFor(String user) { return Integer.toString((int)((System.currentTimeMillis()/30000) % 1_000_000)); }
    boolean verify(String user, String code) { return code.equals(currentCodeFor(user)); }  // time-based, no network
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
